syntax:
```c++
template <size_t N>
struct Factorial {
  static constexpr size_t value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
  static constexpr size_t value = 1;
};

int main() {
  constexpr size_t result = Factorial<5>::value; // 120, calculated at compile time
  std::cout << result << std::endl;
  return 0;
}
```
